issue.body:
Just been looking at capturing Sass compilation errors from gulp-ruby-sass and while the errors are captured and reported, I always get this undefined error. And when the files DO compile successfully, I **still** get the error and no final notify message:

    var gulp = require('gulp'), 
        plumber = require('gulp-plumber'),
        rename = require('gulp-rename'), 
        notify = require('gulp-notify'), 
        sass = require('gulp-ruby-sass'), 
        cssmin = require('gulp-cssmin'),
        header = require('gulp-header'), 
        notifyOptions = {
            title: 'Test',
            sound: 'Frog',
            icon: './ui-theme/images/apple-touch-icon.png',
            onLast: true
        };

    /**
     * Sass theme compilation
     */
    gulp.task('css', function () {
    	
        var notifyOptions = notifyOptions;

        gulp.src('./scss/styles.scss')
        	.pipe(plumber(function (err) { 
            	return notify().write(err);
            }))
            .pipe(sass({
            	style: 'expanded', 
            	lineNumbers: true
            }))
            .pipe(gulp.dest('./assets/css'))
            .pipe(cssmin())
            .pipe(rename({
            	suffix: '.min'}
            ))
            .pipe(gulp.dest('./assets/css'))
            .pipe(notifyOptions);

    });

The Sass files compile fine, so I'm not sure why this error is being thrown.

Is it intended behavior ?

```typescript
function x(f: (g: number) => void): void { f(1); }

x(function (d) {
   // d is number
});
```

Adding parentheses around the function makes 'd' to be any type:

```typescript
function x(f: (g: number) => void): void { f(1); }

x((function (d) {
  // d is any
}));
```

`to5.transform("function* f(xs) {return [for (x of xs) yield x] }", {experimental: true})` generates code involving:

    _toArray(xs).map(function (x) {
          return yield x;
    })

which is not valid ES5 since the `yield` is still there. The same is true of `await`. Using `[for (x of xs) for (y of ys) yield (x+y)]` no longer uses `map`, but still leaves the `yield` in there.

I don't know if `await`/`yield` in list comprehensions is allowed. If it isn't, it should give a compile error rather than generating invalid code.

